namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 uppercase alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
            new() { Id = 4, Name = "English", Abbreviation = "ENG" },
            new() { Id = 5, Name = "History", Abbreviation = "HIST" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, data structures, and object-oriented design principles.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of teaching experience specializing in introductory programming and software engineering.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, CourseCode = "CS 301", Title = "Data Structures and Algorithms", Description = "Advanced study of data structures including trees, graphs, and hash tables. Algorithm design and analysis with emphasis on time and space complexity.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is a former software engineer at Google with extensive research in algorithm optimization and computational complexity theory.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 3, CourseCode = "CS 420", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and practical applications using Python.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Santos", InstructorBio = "Dr. Santos leads the university's AI research lab and has published over 40 papers in top machine learning conferences.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 4, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Liu", InstructorBio = "Dr. Liu specializes in applied mathematics and has authored two widely-used textbooks on linear algebra.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 5, CourseCode = "MATH 301", Title = "Probability and Statistics", Description = "Fundamentals of probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Anna Kowalski", InstructorBio = "Dr. Kowalski brings 20 years of industry experience in statistical modeling before joining academia.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 6, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Laboratory sessions provide hands-on experiments reinforcing theoretical concepts.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is an award-winning educator known for his innovative physics demonstrations and student engagement techniques.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
            new() { Id = 7, CourseCode = "PHYS 305", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, angular momentum, and applications to atomic structure.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Elena Volkov", InstructorBio = "Dr. Volkov is a theoretical physicist whose research focuses on quantum information science and quantum computing.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 8, CourseCode = "ENG 201", Title = "Creative Writing", Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction. Students develop their voice through weekly writing exercises and peer critique.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Prof. David Okafor", InstructorBio = "Prof. Okafor is a published novelist and poet whose work has appeared in The New Yorker and several literary anthologies.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
            new() { Id = 9, CourseCode = "ENG 310", Title = "American Literature: 1900–Present", Description = "Survey of major American literary works from the 20th and 21st centuries, examining themes of identity, culture, and social change.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", InstructorName = "Dr. Lisa Washington", InstructorBio = "Dr. Washington specializes in African American literature and modernist poetry, with particular focus on the Harlem Renaissance.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
            new() { Id = 10, CourseCode = "HIST 101", Title = "World History: Ancient Civilizations", Description = "Survey of ancient civilizations from Mesopotamia to Rome, exploring political systems, cultural achievements, and lasting legacies.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant has led archaeological expeditions in the Mediterranean and brings firsthand field experience to his teaching.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
            new() { Id = 11, CourseCode = "HIST 250", Title = "Modern European History", Description = "Europe from the French Revolution to the present day. Examines industrialization, nationalism, world wars, and European integration.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Claire Müller", InstructorBio = "Dr. Müller studied at the University of Oxford and specializes in 20th-century European political history.", DepartmentId = 5, DepartmentName = "History", IsFeatured = true },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

